package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** The approved six-class selection, with independent reference companion choices. */
final class SurvivorCreationView extends View {
 interface Host{void create(String appearance,String faction,String profession);default void create(String a,String f,String p,String pet){create(a,f,p);}default boolean additionalCharacter(){return false;}default boolean existingSurvivor(){return false;}String status();String legacyProfession();JSONObject definition(String profession);JSONObject previewCharacter();String spawnTown(String faction);void back();}
 static final String[] CLASSES={"melee","ranged","mage","rogue","paladin","necromancer"};
 static final String[] PETS={"wolf","direWolf","horse","warBear","raven","loneWolf","familiar"};
 static final String[] PET_NAMES={"WOLF","DIRE WOLF","HORSE","WAR BEAR","RAVEN","LONE WOLF","FAMILIAR"};
 final Host host;final MenuFrame f=new MenuFrame();final MenuArt art;int sex,body,role,faction,step,companion;float downX,downY;boolean pressed;long changedStep;
 SurvivorCreationView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Choose Melee, Ranged, Mage, Rogue, Paladin or Necromancer; male or female; and one of seven reference companions. Review before confirming.");}
 String appearance(){return(sex==1?"female-":"male-")+(body==1?"2":"1");}
 String allegiance(){return faction==0?"survivor":"bandit";}
 String profession(){return host.legacyProfession().isEmpty()?CLASSES[role]:host.legacyProfession();}
 JSONObject definition(){JSONObject d=host.definition(profession());return d==null?new JSONObject():d;}
 JSONObject preview(){JSONObject saved=host.previewCharacter();try{JSONObject g=saved==null?new JSONObject():new JSONObject(saved.toString()),d=definition();g.put("role",profession()).put("appearance",appearance());if(saved==null)g.put("equippedWeapon",d.optString("weapon")).put("equippedArmour",d.optString("armour")).put("equippedShield",d.optBoolean("shield"));return g;}catch(JSONException e){return new JSONObject();}}
 void back(){if(step>0){step=0;invalidate();}else host.back();}
 protected void onDraw(Canvas c){f.begin(c,this);f.brand(c);f.text(c,step==0?"CHARACTER SELECTION":"CONFIRM CHARACTER",353,45,23,580);boolean legacy=!host.legacyProfession().isEmpty();JSONObject d=definition();
 f.panel(c,24,83,205,315,false);f.text(c,"CHOOSE CLASS",37,108,17,180);if(legacy){f.wrap(c,"Your existing character and progress are retained.",38,148,176,4);f.text(c,profession().toUpperCase(),38,250,18,175);}else for(int i=0;i<CLASSES.length;i++){float y=123+i*42;f.panel(c,36,y,181,36,role==i);f.text(c,CLASSES[i].toUpperCase(),47,y+24,17,160);}
 f.text(c,"MALE",293,368,17,90);f.text(c,"FEMALE",417,368,17,100);art.character(c,preview(),new RectF(260,90,564,344));f.panel(c,275+sex*124,345,112,36,true);f.text(c,sex==0?"MALE":"FEMALE",291+sex*124,369,17,95);
 f.panel(c,592,83,344,315,false);f.text(c,"CHARACTER DETAILS",609,111,19,310);f.text(c,profession().toUpperCase(),609,145,22,310);f.wrap(c,d.optString("description","Your saved character keeps its equipment and progression."),609,174,307,4);f.text(c,legacy?"SAVED EQUIPMENT":"STARTING EQUIPMENT",609,270,14,305);JSONObject kit=d.optJSONObject("items");if(kit!=null){java.util.Iterator<String> keys=kit.keys();int n=0;while(keys.hasNext()&&n<6){String id=keys.next();float x=607+n*50;art.item(c,id,x,284,35);f.text(c,"×"+kit.optInt(id),x,335,12,45);n++;}}
 if(host.existingSurvivor()){f.text(c,"YOUR ALLEGIANCE IS RETAINED",275,409,13,300);}else{f.panel(c,275,388,137,28,faction==0);f.text(c,"SURVIVOR",286,408,14,115);f.panel(c,421,388,137,28,faction==1);f.text(c,"BANDIT",441,408,14,110);}
 f.text(c,"COMPANIONS",28,426,14,210);for(int i=0;i<PETS.length;i++){float x=26+i*131;f.panel(c,x,437,123,47,companion==i);try{art.companionPortrait(c,new JSONObject().put("kind",PETS[i]),new RectF(x+3,441,x+35,479));}catch(JSONException ignored){}f.text(c,PET_NAMES[i],x+39,466,12,80);}
 if(step==1){f.panel(c,240,110,340,235,false);f.text(c,"READY TO ENTER",261,141,22,299);f.text(c,profession().toUpperCase(),261,180,20,299);f.text(c,PET_NAMES[companion],261,213,18,299);f.wrap(c,host.additionalCharacter()?"Unlocks a separate level-one character at the town Character Master. Your existing survivor stays intact.":host.existingSurvivor()?"Your level, items and progress are retained. Choose outdoors in a protected town.":"Starting town: "+host.spawnTown(allegiance()),261,246,294,2);}
 f.panel(c,24,494,170,34,false);f.text(c,"< BACK",47,518,16,137);f.text(c,host.status(),211,518,12,382);f.panel(c,616,494,320,34,true);f.text(c,step==0?"REVIEW SELECTION":host.additionalCharacter()?"UNLOCK CHARACTER":"CONFIRM & ENTER",648,518,18,275);c.restore();}
 public boolean performClick(){super.performClick();return true;}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());int type=e.getActionMasked();if(type==MotionEvent.ACTION_DOWN){pressed=true;downX=x;downY=y;return true;}if(type==MotionEvent.ACTION_CANCEL||type==MotionEvent.ACTION_POINTER_DOWN){pressed=false;return true;}if(type!=MotionEvent.ACTION_UP||!pressed)return true;pressed=false;if(Math.hypot(x-downX,y-downY)>14)return true;performClick();if(step==0){if(host.legacyProfession().isEmpty()&&x>=36&&x<=217&&y>=123&&y<375&&(y-123)%42<=36)role=(int)((y-123)/42);if(y>=345&&y<=381&&x>=275&&x<=523)sex=x>=399?1:0;if(!host.existingSurvivor()&&y>=388&&y<=416&&x>=275&&x<=558)faction=x>=421?1:0;if(host.legacyProfession().isEmpty()&&y>=437&&y<=484&&x>=26&&x<=935&&(x-26)%131<=123)companion=(int)((x-26)/131);}if(y>=494&&y<=528){if(x>=24&&x<=194)back();else if(x>=616&&x<=936){if(step==0){step=1;changedStep=e.getEventTime();}else if(e.getEventTime()-changedStep>=250)host.create(appearance(),allegiance(),profession(),PETS[companion]);}}invalidate();return true;}
}
